{"content": "// In-memory state for active jobs. Keys are job_id, values are status strings.
// Only 'running' jobs are tracked here; cancellation removes them from the map
// so that we never leave timers running or hold stale references.
const jobs = new Map();

function ok(text) {
  return { content: [{ type: 'text', text }] };
}

function fail(code, message) {
  const error = new Error(message);
  error.code = code;
  throw error;
}

export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a background job with the given job_id. Rejects duplicate active jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job.' },
        },
        required: ['job_id'],
        additionalProperties: false,
      },
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job by job_id. Rejects missing jobs or repeated cancellation.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Identifier of the job to cancel.' },
        },
        required: ['job_id'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'start_job':
      return startJob(args);
    case 'cancel_job':
      return cancelJob(args);
    default:
      fail(-32601, `Unknown tool: ${name}`);
  }
}

function startJob({ job_id } = {}) {
  if (typeof job_id !== 'string' || job_id.length === 0) {
    fail(-32602, 'job_id is required and must be a non-empty string');
  }
  if (jobs.has(job_id)) {
    fail(-32602, `Job already active: ${job_id}`);
  }
  jobs.set(job_id, 'running');
  return ok(JSON.stringify({ job_id, status: 'running' }));
}

function cancelJob({ job_id } = {}) {
  if (typeof job_id !== 'string' || job_id.length === 0) {
    fail(-32602, 'job_id is required and must be a non-empty string');
  }
  if (!jobs.has(job_id)) {
    fail(-32602, `Job not found or already cancelled: ${job_id}`);
  }
  jobs.delete(job_id);
  return ok(JSON.stringify({ job_id, status: 'cancelled' }));
}
