{"command": "node --input-type=module -e '
import { listTools, callTool } from "./server.mjs";
const assert = await import("node:assert/strict");

// listTools exposes both tools with additionalProperties:false
const tools = await listTools();
assert.equal(tools.length, 2);
for (const t of tools) {
  assert.equal(t.inputSchema.additionalProperties, false);
  assert.deepEqual(t.inputSchema.required, ["job_id"]);
}

const r1 = await callTool("start_job", { job_id: "j1" });
assert.match(r1.content[0].text, /running/);

// duplicate active job rejected
await assert.rejects(() => callTool("start_job", { job_id: "j1" }), /already active/);

// cancel active job -> cancelled
const c1 = await callTool("cancel_job", { job_id: "j1" });
assert.match(c1.content[0].text, /cancelled/);

// repeated cancellation rejected
await assert.rejects(() => callTool("cancel_job", { job_id: "j1" }), /not found or already cancelled/);

// cancelling missing job rejected
await assert.rejects(() => callTool("cancel_job", { job_id: "missing" }), /not found or already cancelled/);

// unknown tool rejected
await assert.rejects(() => callTool("nope", {}), /Unknown tool/);

// can restart a job after cancellation
const r2 = await callTool("start_job", { job_id: "j1" });
assert.match(r2.content[0].text, /running/);

console.log("ALL EDGE-CASE CHECKS PASSED");
'"}

